import { readFile } from 'node:fs/promises';
const ASSET_FILE = 'mint-asset-file:';
const ASSET_NAMESPACE = 'mint-asset-file';
const ASSET_FILTER = /\.(?:png|jpg|jpeg|gif|webp|avif|woff|woff2|ttf|otf)$/;
export function assetUrlPlugin(side, errorsForPath) {
    return {
        name: 'mint-asset-urls',
        setup(build) {
            build.onLoad({ filter: ASSET_FILTER, namespace: 'file' }, (args) => {
                let value = 'new URL(path, import.meta.url).pathname';
                if (side === 'server') {
                    value = '"/_mintlify/pkg-asset/" + path.replace(/^(?:\\.\\.?\\/)+/, "")';
                }
                return {
                    contents: `import path from ${JSON.stringify(`${ASSET_FILE}${args.path}`)}; export default ${value};`,
                    loader: 'js',
                };
            });
            build.onResolve({ filter: /^mint-asset-file:/ }, (args) => ({
                path: args.path.slice(ASSET_FILE.length),
                namespace: ASSET_NAMESPACE,
            }));
            build.onLoad({ filter: /.*/, namespace: ASSET_NAMESPACE }, async (args) => {
                const errors = errorsForPath(args.path);
                if (errors)
                    return { errors };
                return { contents: new Uint8Array(await readFile(args.path)), loader: 'file' };
            });
        },
    };
}
